REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (124,'vocabulary','expense class','finance.expense_class__t.name — spending category (Electronic, Print, etc.).',NULL,NULL,NULL,NULL,1,'2026-02-19 20:39:13','2026-02-19 20:39:13');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (125,'vocabulary','service point','inventory.service_point__t.name — circulation desk / service location.',NULL,NULL,NULL,NULL,1,'2026-02-19 20:39:13','2026-02-19 20:39:13');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (126,'vocabulary','patron group','users.groups__t.group — patron type (Faculty, Undergraduate, Graduate, Staff).',NULL,NULL,NULL,NULL,1,'2026-02-19 20:39:13','2026-02-19 20:39:13');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (127,'vocabulary','course reserve','courses.coursereserves_courselistings__t — course reserve listings.',NULL,NULL,NULL,NULL,1,'2026-02-19 20:39:13','2026-02-19 20:39:13');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (128,'vocabulary','circulation log','audit.circulation_logs__t — audit trail of circulation events.',NULL,NULL,NULL,NULL,1,'2026-02-19 20:39:13','2026-02-19 20:39:13');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (129,'vocabulary','circulating','circulation.loan__t — count loans to measure circulation. Join item → effective_location_id → location → loclibrary → loccampus for location context.',NULL,NULL,NULL,NULL,1,'2026-02-19 20:39:13','2026-02-19 20:39:13');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (130,'vocabulary','book','inventory.material_type__t where LOWER(name) = \'book\'. The database stores \'Book\' (capitalized). Always use case-insensitive comparison.',NULL,NULL,NULL,NULL,1,'2026-02-19 20:39:13','2026-02-19 20:39:13');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (131,'vocabulary','equipment','inventory.material_type__t where LOWER(name) LIKE \'%equipment%\'. Exclude with AND LOWER(imt.name) NOT LIKE \'%equipment%\'.',NULL,NULL,NULL,NULL,1,'2026-02-19 20:39:13','2026-02-19 20:39:13');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (132,'example',NULL,NULL,'Show me all materials purchased in the last 90 days grouped by material type purchased by Smith College','SELECT imt.name AS material_type_name, SUM(COALESCE(pol.cost__quantity_physical, 1)) AS total_purchased FROM orders.po_line__t AS pol JOIN orders.purchase_order__t AS po ON pol.purchase_order_id = po.id JOIN inventory.material_type__t AS imt ON pol.physical__material_type = imt.id JOIN inventory.location__t AS loc ON pol.physical__expected_receipt_date IS NOT NULL JOIN inventory.loclibrary__t AS lib ON loc.library_id = lib.id JOIN inventory.loccampus__t AS camp ON lib.campus_id = camp.id WHERE camp.name = \'Smith College\' AND po.date_ordered::date >= (CURRENT_DATE - INTERVAL \'90 days\') GROUP BY imt.name ORDER BY total_purchased DESC;',NULL,NULL,1,'2026-02-19 20:39:13','2026-02-19 20:39:13');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (133,'example',NULL,NULL,'How many items does each library have?','SELECT lib.name AS library_name, COUNT(ii.id) AS item_count FROM inventory.item__t AS ii JOIN inventory.location__t AS loc ON ii.effective_location_id = loc.id JOIN inventory.loclibrary__t AS lib ON loc.library_id = lib.id GROUP BY lib.name ORDER BY item_count DESC;',NULL,NULL,1,'2026-02-19 20:39:13','2026-02-19 20:39:13');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (134,'example',NULL,NULL,'What vendors have we spent the most money with this fiscal year?','SELECT org.name AS vendor_name, SUM(inv.total) AS total_spent FROM invoice.invoices__t AS inv JOIN organizations.organizations__t AS org ON inv.vendor_id = org.id WHERE inv.status = \'Paid\' AND inv.invoice_date >= (SELECT start_date FROM finance.fiscal_year__t WHERE code = \'FY2026\') GROUP BY org.name ORDER BY total_spent DESC LIMIT 20;',NULL,NULL,1,'2026-02-19 20:39:13','2026-02-19 20:39:13');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (135,'example',NULL,NULL,'Count checkouts by patron group for the Neilson Library in the last 30 days','SELECT ug.group AS patron_group, COUNT(cl.id) AS checkout_count FROM circulation.loan__t AS cl JOIN users.users__t AS uu ON cl.user_id = uu.id JOIN users.groups__t AS ug ON uu.patron_group = ug.id JOIN inventory.item__t AS ii ON cl.item_id = ii.id JOIN inventory.location__t AS loc ON ii.effective_location_id = loc.id JOIN inventory.loclibrary__t AS lib ON loc.library_id = lib.id WHERE LOWER(lib.name) = LOWER(\'Neilson Library\') AND cl.loan_date >= (CURRENT_DATE - INTERVAL \'30 days\') GROUP BY ug.group ORDER BY checkout_count DESC;',NULL,NULL,1,'2026-02-19 20:39:13','2026-02-19 20:39:13');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (136,'example',NULL,NULL,'Show me the top 10 highest circulating books from Smith College between June 2024 and June 2025','SELECT lib.name AS library_name, ii.effective_call_number_components__call_number AS call_number, inst.title, MAX(cl.loan_date) AS last_circulation_date, COUNT(cl.id) AS circulation_count FROM circulation.loan__t AS cl JOIN inventory.item__t AS ii ON cl.item_id = ii.id JOIN inventory.material_type__t AS imt ON ii.material_type_id = imt.id JOIN inventory.holdings_record__t AS hr ON ii.holdings_record_id = hr.id JOIN inventory.instance__t AS inst ON hr.instance_id = inst.id JOIN inventory.location__t AS loc ON ii.effective_location_id = loc.id JOIN inventory.loclibrary__t AS lib ON loc.library_id = lib.id JOIN inventory.loccampus__t AS camp ON lib.campus_id = camp.id WHERE cl.loan_date::date >= \'2024-06-30\' AND cl.loan_date::date <= \'2025-06-30\' AND LOWER(camp.name) = LOWER(\'Smith College\') AND LOWER(imt.name) = \'book\' AND LOWER(imt.name) NOT LIKE \'%equipment%\' GROUP BY lib.name, ii.effective_call_number_components__call_number, inst.title ORDER BY circulation_count DESC LIMIT 10;',NULL,NULL,1,'2026-02-19 20:39:13','2026-02-19 20:39:13');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (139,'correction',NULL,NULL,'Show me the number of items that have circulated from Smith College to another Five College member. Only show me July 1st, 2024 to June 30th, 2025. I do not want to see items circulated to Smith College patrons only to other members within the Five Colleges.','WITH smith_sp AS (\n  SELECT unnest(array[\n    \'2c0764b7-63b3-4254-9950-0c730b7e438b\',\n    \'6b6b9f00-aac7-4e20-a819-fb24386e48bb\',\n    \'25d98f21-ef4d-4846-955e-17840062b1f0\',\n    \'602aba21-73ae-4e43-a92e-91f2dee34c8f\',\n    \'9e4b06c8-0cb0-4011-ab1d-a23af57d190c\'\n  ])::text AS id\n),\nkeep_materials AS (\n  SELECT unnest(array[\n    \'Book\',\'Journal\',\'Serial\',\'Newspaper\',\'Score\',\n    \'Thesis/Dissertation\',\'Government Publication\',\'Microform\',\n    \'DVD/Blu-ray\',\'Audio CD\',\'CD-ROM\',\'Videocassette\',\n    \'LP Phonorecord\',\'Audiocassette\',\'Film\'\n  ]) AS name\n),\nbase AS (\n  SELECT l.id, l.checkout_service_point_id AS co_sp,\n    l.checkin_service_point_id AS ci_sp,\n    loc.campus_id AS campus_at_co, mt.name AS mtype\n  FROM circulation.loan__t l\n  JOIN inventory.location__t loc ON loc.id = l.item_effective_location_id_at_check_out\n  JOIN inventory.item__t it ON it.id = l.item_id\n  JOIN inventory.material_type__t mt ON mt.id = it.material_type_id\n  WHERE l.loan_date::timestamptz >= \'2024-07-01\'\n    AND l.loan_date::timestamptz < \'2025-06-30\'\n    AND mt.name IN (SELECT name FROM keep_materials)\n    AND l.renewal_count IS NULL\n)\nSELECT\n  SUM(CASE\n    WHEN campus_at_co IN (\n      \'7d02e46d-3e60-4eaf-a986-5aa3550e8cb5\',\n      \'b23a14ae-b3a8-4cbf-92fb-4b81d1a4b0a1\'\n    )\n    AND COALESCE(co_sp, \'\') NOT IN (SELECT id FROM smith_sp)\n    AND co_sp IS NOT NULL\n    THEN 1 ELSE 0\n  END) AS consortial_lending_out\nFROM base;','SELECT COUNT(DISTINCT cl.item_id) AS distinct_items_circulated FROM circulation.loan__t AS cl JOIN inventory.location__t AS loc_item ON cl.item_effective_location_id_at_check_out = loc_item.id JOIN inventory.loccampus__t AS camp_item ON loc_item.campus_id = camp_item.id JOIN users.users__t AS uu ON cl.user_id = uu.id JOIN inventory.loccampus__t AS camp_patron ON uu.custom_fields__institution = camp_patron.id WHERE cl.loan_date::date >= \'2024-07-01\' AND cl.loan_date::date <= \'2025-06-30\' AND LOWER(camp_item.name) = LOWER(\'Smith College\') AND LOWER(camp_patron.name) != LOWER(\'Smith College\') AND camp_patron.institution_id = (SELECT ic.institution_id FROM inventory.loccampus__t AS ic WHERE LOWER(ic.name) = LOWER(\'Smith College\')) LIMIT 100;','CRITICAL: User data is anonymized. NEVER join to users.users__t for campus/institution identification. Instead use checkout_service_point_id and checkin_service_point_id on circulation.loan__t as proxies. Smith-owned items checked out at non-Smith service points = consortial lending out. Also filter to physical material types and exclude renewals (renewal_count IS NULL). Smith campus IDs: 7d02e46d-3e60-4eaf-a986-5aa3550e8cb5 (Smith College), b23a14ae-b3a8-4cbf-92fb-4b81d1a4b0a1 (Repository).',1,'2026-02-19 20:59:41','2026-02-19 20:59:41');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (140,'vocabulary','anonymized data','User/patron records (users.users__t) are ANONYMIZED. NEVER use patron data (custom_fields, patron group joins, user campus fields) to determine which campus or institution a borrower belongs to. Instead, use checkout_service_point_id and checkin_service_point_id on circulation.loan__t as proxies for where transactions happened. Match service point IDs to known campus service points to identify cross-campus activity.',NULL,NULL,NULL,NULL,1,'2026-02-19 21:00:33','2026-02-19 21:00:33');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (141,'vocabulary','consortial circulation','To identify cross-campus lending/borrowing in the Five Colleges consortium, use this approach: (1) Item ownership = item_effective_location_id_at_check_out -> inventory.location__t.campus_id (Smith campus IDs: \'7d02e46d-3e60-4eaf-a986-5aa3550e8cb5\' for Smith College, \'b23a14ae-b3a8-4cbf-92fb-4b81d1a4b0a1\' for Repository). (2) Transaction location = checkout_service_point_id / checkin_service_point_id matched against known campus service points. (3) Lending out = Smith-owned items checked out at NON-Smith service points. (4) Borrowing in = non-Smith-owned items checked out at Smith service points. NEVER use users.users__t joins — data is anonymized.',NULL,NULL,NULL,NULL,1,'2026-02-19 21:00:33','2026-02-19 21:00:33');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (142,'vocabulary','consortial lending','Same as \'consortial circulation\'. Lending out = Smith-owned items (campus_at_co in Smith/Repository campus IDs) where checkout_service_point_id is NOT a Smith service point. Use service points as proxy — NOT user/patron data (anonymized).',NULL,NULL,NULL,NULL,1,'2026-02-19 21:00:33','2026-02-19 21:00:33');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (143,'vocabulary','consortial borrowing','Same as \'consortial circulation\'. Borrowing in = non-Smith-owned items (campus_at_co NOT in Smith/Repository campus IDs) where checkout_service_point_id IS a Smith service point. Use service points as proxy — NOT user/patron data (anonymized).',NULL,NULL,NULL,NULL,1,'2026-02-19 21:00:33','2026-02-19 21:00:33');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (144,'vocabulary','Smith College service points','Smith College service point UUIDs for identifying transactions at Smith: \'2c0764b7-63b3-4254-9950-0c730b7e438b\' (SC Neilson Library), \'6b6b9f00-aac7-4e20-a819-fb24386e48bb\' (SC Self Check), \'25d98f21-ef4d-4846-955e-17840062b1f0\' (SC Hillyer Art Library), \'602aba21-73ae-4e43-a92e-91f2dee34c8f\' (SC Josten Library), \'9e4b06c8-0cb0-4011-ab1d-a23af57d190c\' (SC Annex). Use with checkout_service_point_id / checkin_service_point_id on circulation.loan__t.',NULL,NULL,NULL,NULL,1,'2026-02-19 21:00:33','2026-02-19 21:00:33');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (145,'vocabulary','Smith College campus IDs','Smith College campus UUIDs in inventory.loccampus__t for determining item ownership via item_effective_location_id_at_check_out -> location.campus_id: \'7d02e46d-3e60-4eaf-a986-5aa3550e8cb5\' (Smith College campus), \'b23a14ae-b3a8-4cbf-92fb-4b81d1a4b0a1\' (Repository campus — also Smith-owned). Both should be included when identifying Smith-owned items.',NULL,NULL,NULL,NULL,1,'2026-02-19 21:00:33','2026-02-19 21:00:33');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (146,'vocabulary','renewal','circulation.loan__t.renewal_count — number of times a loan was renewed. When counting initial checkouts only (e.g. for circulation statistics), filter with renewal_count IS NULL to exclude renewal records and count only original checkouts.',NULL,NULL,NULL,NULL,1,'2026-02-19 21:00:33','2026-02-19 21:00:33');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (147,'vocabulary','physical materials','When filtering for physical/tangible materials (excluding equipment and e-resources), use this list of material_type__t.name values: \'Book\', \'Journal\', \'Serial\', \'Newspaper\', \'Score\', \'Thesis/Dissertation\', \'Government Publication\', \'Microform\', \'DVD/Blu-ray\', \'Audio CD\', \'CD-ROM\', \'Videocassette\', \'LP Phonorecord\', \'Audiocassette\', \'Film\'. Build as a CTE with unnest(array[...]) for clean filtering.',NULL,NULL,NULL,NULL,1,'2026-02-19 21:00:33','2026-02-19 21:00:33');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (148,'example',NULL,NULL,'Show me Smith College physical circulation at Smith, consortial lending out, and consortial borrowing in for FY 2024-2025 (July 1 to June 30)','WITH smith_sp AS (\n  SELECT unnest(array[\n    \'2c0764b7-63b3-4254-9950-0c730b7e438b\',\n    \'6b6b9f00-aac7-4e20-a819-fb24386e48bb\',\n    \'25d98f21-ef4d-4846-955e-17840062b1f0\',\n    \'602aba21-73ae-4e43-a92e-91f2dee34c8f\',\n    \'9e4b06c8-0cb0-4011-ab1d-a23af57d190c\'\n  ])::text AS id\n),\nkeep_materials AS (\n  SELECT unnest(array[\n    \'Book\',\'Journal\',\'Serial\',\'Newspaper\',\'Score\',\n    \'Thesis/Dissertation\',\'Government Publication\',\'Microform\',\n    \'DVD/Blu-ray\',\'Audio CD\',\'CD-ROM\',\'Videocassette\',\n    \'LP Phonorecord\',\'Audiocassette\',\'Film\'\n  ]) AS name\n),\nbase AS (\n  SELECT l.id, l.loan_date::timestamptz AS loan_dt,\n    l.checkout_service_point_id AS co_sp,\n    l.checkin_service_point_id AS ci_sp,\n    loc.campus_id AS campus_at_co, mt.name AS mtype\n  FROM circulation.loan__t l\n  JOIN inventory.location__t loc ON loc.id = l.item_effective_location_id_at_check_out\n  JOIN inventory.item__t it ON it.id = l.item_id\n  JOIN inventory.material_type__t mt ON mt.id = it.material_type_id\n  WHERE l.loan_date::timestamptz >= \'2024-07-01\'\n    AND l.loan_date::timestamptz < \'2025-06-30\'\n    AND mt.name IN (SELECT name FROM keep_materials)\n    AND l.renewal_count IS NULL\n)\nSELECT\n  SUM(CASE\n    WHEN campus_at_co IN (\'7d02e46d-3e60-4eaf-a986-5aa3550e8cb5\',\'b23a14ae-b3a8-4cbf-92fb-4b81d1a4b0a1\')\n    AND co_sp IN (SELECT id FROM smith_sp)\n    AND (ci_sp IS NULL OR ci_sp IN (SELECT id FROM smith_sp))\n    THEN 1 ELSE 0\n  END) AS physical_circ_at_smith,\n  SUM(CASE\n    WHEN campus_at_co IN (\'7d02e46d-3e60-4eaf-a986-5aa3550e8cb5\',\'b23a14ae-b3a8-4cbf-92fb-4b81d1a4b0a1\')\n    AND COALESCE(co_sp, \'\') NOT IN (SELECT id FROM smith_sp)\n    AND co_sp IS NOT NULL\n    THEN 1 ELSE 0\n  END) AS consortial_lending_out,\n  SUM(CASE\n    WHEN campus_at_co NOT IN (\'7d02e46d-3e60-4eaf-a986-5aa3550e8cb5\',\'b23a14ae-b3a8-4cbf-92fb-4b81d1a4b0a1\')\n    AND co_sp IN (SELECT id FROM smith_sp)\n    THEN 1 ELSE 0\n  END) AS consortial_borrowing_in\nFROM base;',NULL,NULL,1,'2026-02-19 21:00:33','2026-02-19 21:00:33');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (149,'vocabulary','campus abbreviation SC','SC = Smith College. Library and location names prefixed with SC belong to Smith College (e.g. SC Neilson Library, SC Hillyer Art Library).',NULL,NULL,NULL,'Five Colleges naming convention',1,'2026-02-20 15:33:47','2026-02-20 15:33:47');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (150,'vocabulary','campus abbreviation AC','AC = Amherst College. Library and location names prefixed with AC belong to Amherst College (e.g. AC Frost Library, AC Science Library).',NULL,NULL,NULL,'Five Colleges naming convention',1,'2026-02-20 15:33:52','2026-02-20 15:33:52');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (151,'vocabulary','campus abbreviation MH','MH = Mount Holyoke College. Library and location names prefixed with MH belong to Mount Holyoke College (e.g. MH Main Library).',NULL,NULL,NULL,'Five Colleges naming convention',1,'2026-02-20 15:34:56','2026-02-20 15:34:56');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (152,'vocabulary','campus abbreviation UM','UM = University Of Massachusetts. Library and location names prefixed with UM belong to UMass (e.g. UM W.E.B. Du Bois Library).',NULL,NULL,NULL,'Five Colleges naming convention',1,'2026-02-20 15:34:56','2026-02-20 15:34:56');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (153,'vocabulary','campus abbreviation HC','HC = Hampshire College. Library and location names prefixed with HC belong to Hampshire College (e.g. HC Harold Johnson Library).',NULL,NULL,NULL,'Five Colleges naming convention',1,'2026-02-20 15:34:56','2026-02-20 15:34:56');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (154,'vocabulary','campus abbreviation RP','RP = Five Colleges Collections. Library and location names prefixed with RP belong to the shared Five Colleges repository.',NULL,NULL,NULL,'Five Colleges naming convention',1,'2026-02-20 15:34:56','2026-02-20 15:34:56');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (155,'vocabulary','campus abbreviation YB','YB = National Yiddish Book Center. Library and location names prefixed with YB belong to the Yiddish Book Center.',NULL,NULL,NULL,'Five Colleges naming convention',1,'2026-02-20 15:34:56','2026-02-20 15:34:56');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (156,'vocabulary','location naming convention','In this Five Colleges FOLIO instance, ALL library names and location names are prefixed with a 2-letter campus abbreviation code (SC, AC, MH, UM, HC, RP, YB). When searching for a library or location by name, use ILIKE with a wildcard pattern to match regardless of prefix, e.g. WHERE name ILIKE \'%Neilson%\' instead of exact match.',NULL,NULL,NULL,'Five Colleges naming convention - general rule',1,'2026-02-20 15:34:56','2026-02-20 15:34:56');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (157,'example','items at Neilson Library',NULL,'How many items are at Neilson Library?','SELECT COUNT(*) AS item_count FROM inventory.item__t ii JOIN inventory.location__t il ON ii.effective_location_id = il.id JOIN inventory.loclibrary__t ilb ON il.library_id = ilb.id WHERE ilb.name ILIKE \'%Neilson%\'',NULL,'Demonstrates using ILIKE wildcard for campus-prefixed library name (SC Neilson Library)',1,'2026-02-20 15:34:56','2026-02-20 15:34:56');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (158,'example','Smith College libraries',NULL,'List all libraries at Smith College','SELECT ilb.name AS library_name, ilb.code AS library_code FROM inventory.loclibrary__t ilb JOIN inventory.loccampus__t ic ON ilb.campus_id = ic.id WHERE ic.name ILIKE \'%Smith%\' ORDER BY ilb.name',NULL,'Demonstrates joining library to campus to filter by campus name',1,'2026-02-20 15:34:56','2026-02-20 15:34:56');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (159,'correction',NULL,NULL,'I want to see the entire library budget at Smith College. I want to look across multiple years from 2022 to current.','        SELECT \n            fyt.\"name\" AS fiscal_year, \n            SUM(bt.allocated) AS total_allocated\n        FROM \n            ldplite.finance.budget__t bt \n        INNER JOIN \n            ldplite.finance.fund__t ft ON bt.fund_id = ft.id\n        INNER JOIN \n            ldplite.finance.fiscal_year__t fyt ON bt.fiscal_year_id = fyt.id\n        WHERE \n            fyt.series = \'SCFY\'\n        GROUP BY \n            fyt.\"name\"\n        ORDER BY \n            fyt.\"name\"','SELECT\n  ffy.name AS fiscal_year,\n  SUM(fb.total_funding) AS total_budget_amount\nFROM finance.budget__t AS fb\nJOIN finance.fiscal_year__t AS ffy\n  ON fb.fiscal_year_id = ffy.id\nJOIN finance.budget__t__acq_unit_ids AS fbau\n  ON fb.id = fbau.id\nJOIN orders.acquisitions_unit__t AS oau\n  ON fbau.acq_unit_ids = oau.id\nWHERE\n  LOWER(oau.name) ILIKE \'%smith college%\' AND ffy.period_start::date >= \'2022-01-01\'\nGROUP BY\n  ffy.name\nORDER BY\n  ffy.name;','Questions about budget allocations should use fiscal_year__t and focus on the series which is the fiscal year allocation. Institutions use the abbreviation over their institution, SC for Smith College for example, to get their data.',1,'2026-02-20 15:55:29','2026-02-20 15:55:29');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (160,'vocabulary','academic year','When a user says \'current year\', \'this year\', or \'academic year\', they mean the academic/fiscal year running July 1 through June 30. Never assume calendar year (Jan-Dec) unless the user explicitly says \'calendar year\'. To calculate the current academic year dynamically, ALWAYS use a CTE with the WITH keyword: WITH academic_year_dates AS ( SELECT CASE WHEN CURRENT_DATE >= date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\' THEN date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\' ELSE date_trunc(\'year\', CURRENT_DATE) - INTERVAL \'6 months\' END AS start_date, CASE WHEN CURRENT_DATE >= date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\' THEN date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'1 year\' + INTERVAL \'6 months\' - INTERVAL \'1 day\' ELSE date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\' - INTERVAL \'1 day\' END AS end_date ) — then reference it with: JOIN academic_year_dates ayd ON TRUE and filter with: WHERE date_column >= ayd.start_date AND date_column <= ayd.end_date. CRITICAL: The WITH keyword and CTE name \'academic_year_dates AS (\' must appear at the start of the query. If the query has other CTEs, chain them with commas after the academic_year_dates CTE.',NULL,NULL,NULL,'Five Colleges academic year - July 1 to June 30. Updated to emphasize WITH CTE wrapper.',1,'2026-02-20 15:59:50','2026-02-24 15:49:12');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (161,'vocabulary','circulation data','Circulation data comes from TWO sources: (1) Current FOLIO circulation from circulation.loan__t (preferred, ~677K rows, faster) — columns use DIRECT names: item_id, loan_date, action, due_date, return_date, renewal_count, status__name. Filter checkouts with: action IN (\'checkedout\', \'checkedOutThroughOverride\'). Group by item_id. Do NOT use loan__ prefix on columns (that prefix is only for audit_loan__t). (2) Historic/former circulation from the ALEPH system (migrated in 2022), stored in inventory.item__t__notes where notes__item_note_type_id = \'f765f19f-9f1c-4688-8c79-ec366a730842\'. The note value is a plain text number that must be extracted with CAST(COALESCE(NULLIF(REGEXP_REPLACE(notes__note, \'\\D\', \'\', \'g\'), \'\'), \'0\') AS INTEGER). Join historic data to items via hrid (item__t__notes.hrid = item__t.hrid). When the user asks for TOTAL, LIFETIME, ALL-TIME, CUMULATIVE, or HIGHEST circulating items, include BOTH sources as separate columns plus a combined total: COALESCE(current, 0) + COALESCE(former, 0). When the user asks for circulation within a specific TIME PERIOD (e.g. \'this year\', \'last 30 days\'), use ONLY the current FOLIO circulation data — historic ALEPH data has no date granularity. IMPORTANT: Always prefer loan__t over audit_loan__t — loan__t is 3x smaller and has cleaner column names.',NULL,NULL,NULL,NULL,1,'2026-02-20 19:45:54','2026-02-24 16:40:43');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (162,'vocabulary','former circulation','\"Former circulation\", \"historic circulation\", or \"ALEPH circulation\", \"Cumulative circulation\", \"Total Circulation\" refers to cumulative checkout counts migrated from the ALEPH ILS into FOLIO item notes. Located in inventory.item__t__notes where notes__item_note_type_id = \'f765f19f-9f1c-4688-8c79-ec366a730842\'. The note contains a plain-text number. Extract it with: CAST(COALESCE(NULLIF(REGEXP_REPLACE(notes__note, \'\\D\', \'\', \'g\'), \'\'), \'0\') AS INTEGER). Join to item__t on hrid. Always LEFT JOIN since not all items have historic data.',NULL,NULL,NULL,NULL,1,'2026-02-20 19:47:09','2026-02-20 19:47:09');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (163,'example',NULL,NULL,'Show the highest circulating items at a specific library with total circulation','WITH target_items AS (\n    SELECT ii.id AS item_id, ii.hrid, ii.barcode,\n           ii.effective_call_number_components__call_number AS call_number,\n           inst.title AS instance_title,\n           mtt.name AS material_type,\n           loc.name AS location_name\n    FROM inventory.item__t ii\n    JOIN inventory.holdings_record__t hr ON ii.holdings_record_id = hr.id\n    JOIN inventory.instance__t inst ON hr.instance_id = inst.id\n    JOIN inventory.material_type__t imt ON ii.material_type_id = imt.id\n    JOIN inventory.location__t loc ON ii.effective_location_id = loc.id\n    JOIN inventory.loclibrary__t lib ON loc.library_id = lib.id\n    WHERE lib.name ILIKE \'%Neilson%\'\n      AND LOWER(imt.name) = \'book\'\n),\ncurrent_circ AS (\n    SELECT cl.item_id,\n           COUNT(*) AS current_circulation,\n           MAX(cl.loan_date) AS last_circulation_date\n    FROM circulation.loan__t cl\n    JOIN target_items ti ON cl.item_id = ti.item_id\n    WHERE cl.action IN (\'checkedout\', \'checkedOutThroughOverride\')\n    GROUP BY cl.item_id\n),\nformer_circ AS (\n    SELECT itn.hrid,\n           CAST(COALESCE(NULLIF(REGEXP_REPLACE(itn.notes__note, \'\\D\', \'\', \'g\'), \'\'), \'0\') AS INTEGER) AS former_circulation\n    FROM inventory.item__t__notes itn\n    JOIN target_items ti ON itn.hrid = ti.hrid\n    WHERE itn.notes__item_note_type_id = \'f765f19f-9f1c-4688-8c79-ec366a730842\'\n)\nSELECT\n    ti.instance_title,\n    ti.barcode AS item_barcode,\n    ti.call_number,\n    ti.material_type,\n    ti.location_name,\n    COALESCE(cc.current_circulation, 0) AS current_circulation,\n    COALESCE(fc.former_circulation, 0) AS former_circulation,\n    COALESCE(cc.current_circulation, 0) + COALESCE(fc.former_circulation, 0) AS total_circulation,\n    cc.last_circulation_date\nFROM target_items ti\nLEFT JOIN current_circ cc ON ti.item_id = cc.item_id\nLEFT JOIN former_circ fc ON ti.hrid = fc.hrid\nORDER BY total_circulation DESC\nLIMIT 100',NULL,'OPTIMIZED pattern using loan__t (NOT audit_loan__t). Defines target_items CTE first with all filters (location, material type), then current_circ and former_circ CTEs JOIN to target_items to only aggregate matching items. Uses circulation.loan__t with direct column names (item_id, action, loan_date — NO loan__ prefix). This query completes in ~220 seconds for 271K items. ALWAYS use this CTE pattern for circulation queries.',1,'2026-02-20 19:47:38','2026-02-24 16:46:27');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (164,'example','items created this year',NULL,'How many items were created this year?','WITH academic_year_dates AS (\n    SELECT\n        CASE\n            WHEN CURRENT_DATE >= date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\'\n            THEN date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\'\n            ELSE date_trunc(\'year\', CURRENT_DATE) - INTERVAL \'6 months\'\n        END AS start_date,\n        CASE\n            WHEN CURRENT_DATE >= date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\'\n            THEN date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'1 year\' + INTERVAL \'6 months\' - INTERVAL \'1 day\'\n            ELSE date_trunc(\'year\', CURRENT_DATE) + INTERVAL \'6 months\' - INTERVAL \'1 day\'\n        END AS end_date\n)\nSELECT COUNT(*) AS items_created\nFROM inventory.item__t i, academic_year_dates a\nWHERE i.metadata__created_date >= a.start_date\nAND i.metadata__created_date <= a.end_date',NULL,'Demonstrates the academic year CTE pattern. CRITICAL: query must start with WITH academic_year_dates AS ( ... ) — do not omit the WITH keyword.',1,'2026-02-24 15:49:12','2026-02-24 15:49:12');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (165,'vocabulary','query performance optimization','CRITICAL PERFORMANCE RULES: (1) Always use circulation.loan__t (NOT audit_loan__t) for circulation queries — it is 3x smaller (677K vs 2.2M rows) and has cleaner column names (item_id, action, loan_date — no loan__ prefix). (2) When a query uses CTEs (WITH clauses) that aggregate large tables (e.g. circulation.loan__t, inventory.item__t__notes), ALWAYS define a target_items CTE FIRST that applies all WHERE filters (location, campus, material type, etc.), then JOIN the circulation/notes CTEs to target_items. BAD pattern (timeout): CTE aggregates ALL rows, outer query filters. GOOD pattern (fast): target_items CTE with filters first, then circulation CTE joins to target_items. (3) For circulation.loan__t columns: use item_id (NOT loan__item_id), action (NOT loan__action), loan_date (NOT loan__loan_date). The loan__ prefix columns are ONLY in audit_loan__t. (4) Filter checkouts with: action IN (\'checkedout\', \'checkedOutThroughOverride\').',NULL,NULL,NULL,'Prevents timeout on large circulation/notes aggregation queries',1,'2026-02-24 16:00:38','2026-02-24 16:40:43');
REPLACE INTO `ai_training_hints` (`id`, `type`, `hint_key`, `hint_value`, `example_question`, `example_sql`, `original_sql`, `notes`, `is_active`, `created_at`, `updated_at`) VALUES (166,'example','highest circulating books optimized',NULL,'Show the highest circulating books at Neilson Library with total circulation','WITH target_items AS (\n    SELECT ii.id AS item_id, ii.hrid, ii.barcode,\n           ii.effective_call_number_components__call_number AS call_number,\n           inst.title AS instance_title\n    FROM inventory.item__t ii\n    JOIN inventory.holdings_record__t hr ON ii.holdings_record_id = hr.id\n    JOIN inventory.instance__t inst ON hr.instance_id = inst.id\n    JOIN inventory.material_type__t imt ON ii.material_type_id = imt.id\n    JOIN inventory.location__t loc ON ii.effective_location_id = loc.id\n    JOIN inventory.loclibrary__t lib ON loc.library_id = lib.id\n    WHERE lib.name ILIKE \'%Neilson%\'\n      AND LOWER(imt.name) = \'book\'\n),\ncurrent_circ AS (\n    SELECT cl.item_id,\n           COUNT(*) AS current_circulation,\n           MAX(cl.loan_date) AS last_circulation_date\n    FROM circulation.loan__t cl\n    JOIN target_items ti ON cl.item_id = ti.item_id\n    WHERE cl.action IN (\'checkedout\', \'checkedOutThroughOverride\')\n    GROUP BY cl.item_id\n),\nformer_circ AS (\n    SELECT itn.hrid,\n           CAST(COALESCE(NULLIF(REGEXP_REPLACE(itn.notes__note, \'\\D\', \'\', \'g\'), \'\'), \'0\') AS INTEGER) AS former_circulation\n    FROM inventory.item__t__notes itn\n    JOIN target_items ti ON itn.hrid = ti.hrid\n    WHERE itn.notes__item_note_type_id = \'f765f19f-9f1c-4688-8c79-ec366a730842\'\n)\nSELECT\n    ti.instance_title,\n    ti.barcode AS item_barcode,\n    ti.call_number,\n    COALESCE(cc.current_circulation, 0) AS current_circulation,\n    COALESCE(fc.former_circulation, 0) AS former_circulation,\n    COALESCE(cc.current_circulation, 0) + COALESCE(fc.former_circulation, 0) AS total_circulation,\n    cc.last_circulation_date\nFROM target_items ti\nLEFT JOIN current_circ cc ON ti.item_id = cc.item_id\nLEFT JOIN former_circ fc ON ti.hrid = fc.hrid\nORDER BY total_circulation DESC\nLIMIT 20',NULL,'OPTIMIZED pattern using loan__t (NOT audit_loan__t). Defines target_items CTE first with all filters (location, material type), then current_circ and former_circ CTEs JOIN to target_items to only aggregate matching items. Uses circulation.loan__t with direct column names: item_id (NOT loan__item_id), action (NOT loan__action), loan_date (NOT loan__loan_date). Tested: completes in ~220 seconds for Neilson Library (271K books). ALWAYS use this 3-CTE pattern for circulation queries.',1,'2026-02-24 16:00:38','2026-02-24 16:46:27');
